import argparse
import json
import os

import yaml
from graphql import parse
from graphql.utilities import build_ast_schema, build_client_schema
from openai import OpenAI

# Default model
DEFAULT_MODEL = "gpt-5"

# Output mapping: API name -> (subdirectory under promptfoo, filename)
# Note: These map to coverage test files in dev-mcp that correspond to coverage tests
# in shopify-dev. For example, shopify-dev's admin_coverage_tests.yaml
# maps to dev-mcp's admin/coverage_tests.yaml
OUTPUT_MAP = {
    "admin": ("admin", "coverage_tests.yaml"),
    "customer": (".", "customer.yaml"),
    "partner": (".", "partner.yaml"),
    "storefront": (".", "storefront-graphql.yaml"),
    "payments": (".", "payments_apps.yaml"),
    "shipping": (".", "shipping.yaml"),
}

# Mapping of API names to their schema file patterns
# Note: Query and Mutation type names are now auto-detected from the schema
API_CONFIGS = {
    "admin": {
        "type": "graphql",
        "path_pattern": "db/schemas/admin_graphql/admin_schema_{version}_public.graphql",
        "json_path_pattern": "db/data/docs/graphql/raw/admin_{version}.json",
    },
    "storefront": {
        "type": "json",
        "path_pattern": "db/data/docs/graphql/raw/storefront_{version}.json",
    },
    "partner": {
        "type": "json",
        "path_pattern": "db/data/docs/graphql/raw/partner_{version}.json",
    },
    "customer": {  # customer-account API
        "type": "json",
        "path_pattern": "db/data/docs/graphql/raw/customer_{version}.json",
    },
    "payments": {  # payments_apps API
        "type": "json",
        "path_pattern": "db/data/docs/graphql/raw/payments_apps_{version}.json",
    },
    "shipping": {  # shipping_partner_platform API
        "type": "json",
        "path_pattern": "db/data/docs/graphql/raw/shipping_partner_platform_{version}.json",
    },
}


def generate_yaml_file(actions, api_name, promptfoo_dir):
    yaml_list = []

    for action_type in ["queries", "mutations"]:
        for action in actions[action_type]:
            entry = {
                "description": "coverage test",
                "vars": {
                    "prompt": action["action"],
                    "matches": f"```graphql.*{action['name']}.*```",
                },
            }
            yaml_list.append(entry)

    # Resolve output path based on mapping
    if api_name not in OUTPUT_MAP:
        raise ValueError(f"No output mapping configured for API '{api_name}'")
    subdir, filename = OUTPUT_MAP[api_name]
    output_dir = os.path.join(promptfoo_dir, subdir)
    os.makedirs(output_dir, exist_ok=True)
    output_file = os.path.join(output_dir, filename)
    
    # Check if target is a wrapper config (dict) or pure test file (list)
    if os.path.exists(output_file):
        with open(output_file, "r") as f:
            file_content = f.read()
            
        try:
            existing_data = yaml.safe_load(file_content)
            if isinstance(existing_data, dict) and "tests" in existing_data:
                # Check if tests uses file references (list of strings)
                if isinstance(existing_data["tests"], list) and existing_data["tests"]:
                    if isinstance(existing_data["tests"][0], str):
                        # File references - don't touch this file
                        print(f"⚠️  Skipping {output_file} - uses external file references")
                        print(f"   Current: {existing_data['tests']}")
                        print(f"   To regenerate, update mapping to point to the referenced file")
                        return
                
                # Wrapper config with inline tests - text-based replacement to preserve formatting
                print(f"Updating wrapper config: preserving prompts/providers/assertions")
                
                # Find the "tests:" line and replace everything after it
                lines = file_content.split('\n')
                tests_line_idx = None
                for i, line in enumerate(lines):
                    if line.strip() == 'tests:' or line.startswith('tests:'):
                        tests_line_idx = i
                        break
                
                if tests_line_idx is not None:
                    # Keep everything up to and including "tests:" line
                    new_content = '\n'.join(lines[:tests_line_idx + 1]) + '\n'
                    
                    # Add new tests with proper indentation (each test indented 2 spaces)
                    test_yaml = yaml.dump(yaml_list, default_flow_style=False, sort_keys=False)
                    # Indent each line by 2 spaces (for tests: array items)
                    indented_tests = '\n'.join('  ' + line if line else line for line in test_yaml.split('\n'))
                    new_content += indented_tests
                    
                    with open(output_file, "w") as out:
                        out.write(new_content)
                    print(f"Updated {output_file} with {len(yaml_list)} test cases (preserved wrapper)")
                    return
        except:
            pass  # Fall through to overwrite
    
    # Pure test file or doesn't exist - write directly
    with open(output_file, "w") as file:
        yaml.dump(yaml_list, file, default_flow_style=False, sort_keys=False)

    print(f"Generated {output_file} with {len(yaml_list)} test cases")


def fetch_gpt4_turbo_actions(name, description, type, api_name="admin"):
    # Create OpenAI client
    client = OpenAI(
        api_key=os.getenv("OPENAI_API_KEY"),
        base_url=os.getenv("OPENAI_API_BASE_URL")
    )

    api_display_name = api_name.title()
    if api_name == "customer":
        api_display_name = "Customer Account"
    elif api_name == "payments":
        api_display_name = "Payments Apps"
    elif api_name == "shipping":
        api_display_name = "Shipping Partner Platform"

    prompt_text = (
        f"Given this {type} in our Shopify {api_display_name} API:\n\n{name}\n"
        f"Here is the description for this operation: ```{description}```\n\n"
        f"Generate an action that a user might want to perform.\n"
        "Make sure to distinguish between singular and plural. For example a 'ingredient' query fetches a single ingredient, while a `ingredients` query fetches multiple ingredients.\n"
        f"When the action involves listing all items or fetching all resources, append 'accessible from the {api_display_name.lower()} API' or similar context.\n\n"
    )
    example_queries = f"""
        These are some examples:

        ## query product
        Fetch last 3 products

        ## query product
        Fetch a product by ID

        ## query metafieldDefinitions
        List all metafield definitions accessible from the EXAMPLE_API_NAME

        ## query metafieldDefinitionTypes
        List all metafield definition types accessible from the EXAMPLE_API_NAME

        ## query marketByGeography
        Fetch a market by country code

        Here is your task:

        ## query {name}
        """
    example_mutations = f"""
        These are some examples:

        ## mutation draftOrderCreate
        Create a draft order with a custom price

        ## mutation discountCodeBasicCreate
        Create a basic product discount for the products with the tag 'tee'

        ## metafieldDefinitionDelete
        Delete a metafield definition

        ## mutation giftCardDisable
        Disable a gift card and return the gift card balance

        ## mutation discountCodeBulkActivate
        Activate code discounts in bulk

        Here is your task:

        ## mutation {name}
        """

    prompt_examples = example_queries if type == "query" else example_mutations

    completion_args = {
        "model": DEFAULT_MODEL,
        "messages": [{"role": "user", "content": prompt_text + prompt_examples}],
    }

    if not DEFAULT_MODEL.startswith("gpt-5"):
        completion_args["temperature"] = 0.1

    completion = client.chat.completions.create(**completion_args)

    return completion.choices[0].message.content.split("\n")[-1]


def generate_actions(info, api_name="admin"):
    actions = {"queries": [], "mutations": []}

    for query in info["queries"]:
        action = fetch_gpt4_turbo_actions(
            query["name"], query["description"], "query", api_name
        )
        print(f"Action for query {query['name']}({query['description']}): {action}")
        actions["queries"].append({"name": query["name"], "action": action})

    for mutation in info["mutations"]:
        action = fetch_gpt4_turbo_actions(
            mutation["name"], mutation["description"], "mutation", api_name
        )
        print(f"Action for mutation {mutation['name']}: {action}")
        actions["mutations"].append({"name": mutation["name"], "action": action})

    return actions


def extract_queries_mutations_from_graphql(
    schema_file, query_type_name="QueryRoot", mutation_type_name="MutationRoot"
):
    with open(schema_file, "r") as file:
        schema_content = file.read()

    ast = parse(schema_content)
    schema = build_ast_schema(ast)

    query_type = schema.query_type if hasattr(schema, "query_type") else None
    mutation_type = schema.mutation_type if hasattr(schema, "mutation_type") else None

    query_type_name = query_type.name if query_type else "QueryRoot"
    mutation_type_name = mutation_type.name if mutation_type else "MutationRoot"

    print(
        f"  Detected types - Query: {query_type_name}, Mutation: {mutation_type_name}"
    )

    result = {"queries": [], "mutations": []}

    if query_type:
        for field_name, field in query_type.fields.items():
            if not field.deprecation_reason:
                item = {
                    "name": field_name,
                    "description": field.description.strip()
                    if field.description
                    else "No description provided",
                }
                result["queries"].append(item)

    if mutation_type:
        for field_name, field in mutation_type.fields.items():
            if not field.deprecation_reason:
                item = {
                    "name": field_name,
                    "description": field.description.strip()
                    if field.description
                    else "No description provided",
                }
                result["mutations"].append(item)

    return result


def extract_queries_mutations_from_json(
    json_file, query_type_name="QueryRoot", mutation_type_name="Mutation"
):
    with open(json_file, "r") as file:
        introspection_data = json.load(file)

    schema_data = introspection_data["data"]["__schema"]
    actual_query_type = (
        schema_data.get("queryType", {}).get("name")
        if schema_data.get("queryType")
        else None
    )
    actual_mutation_type = (
        schema_data.get("mutationType", {}).get("name")
        if schema_data.get("mutationType")
        else None
    )

    if actual_query_type:
        query_type_name = actual_query_type
    if actual_mutation_type:
        mutation_type_name = actual_mutation_type

    print(
        f"  Detected types - Query: {query_type_name}, Mutation: {mutation_type_name}"
    )

    schema = build_client_schema(introspection_data["data"])

    result = {"queries": [], "mutations": []}

    query_type = schema.get_type(query_type_name)
    mutation_type = schema.get_type(mutation_type_name)

    if query_type:
        for field_name, field in query_type.fields.items():
            if not field.deprecation_reason:
                item = {
                    "name": field_name,
                    "description": field.description.strip()
                    if field.description
                    else "No description provided",
                }
                result["queries"].append(item)

    if mutation_type:
        for field_name, field in mutation_type.fields.items():
            if not field.deprecation_reason:
                item = {
                    "name": field_name,
                    "description": field.description.strip()
                    if field.description
                    else "No description provided",
                }
                result["mutations"].append(item)

    return result


def main():
    parser = argparse.ArgumentParser(
        description="Generate GraphQL API coverage test cases for Shopify APIs"
    )
    parser.add_argument(
        "--api",
        type=str,
        default="admin",
        choices=["admin", "storefront", "partner", "customer", "payments", "shipping"],
        help="The API to generate test cases for (default: admin)",
    )
    parser.add_argument(
        "--version",
        type=str,
        required=True,
        help="The API version to use (e.g., 2025-10, 2025-01)",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Just extract queries/mutations without generating test cases",
    )

    args = parser.parse_args()
    api_name = args.api
    version = args.version
    # Determine shopify-dev root (standard path, optional env override)
    shopify_dev_root = os.getenv(
        "SHOPIFY_DEV_ROOT",
        os.path.expanduser("~/src/github.com/Shopify/shopify-dev"),
    )
    if not os.path.isdir(shopify_dev_root):
        print(
            f"Error: Could not find shopify-dev repository at '{shopify_dev_root}'.\n"
            "Set SHOPIFY_DEV_ROOT or clone to ~/src/github.com/Shopify/shopify-dev."
        )
        return

    if api_name not in API_CONFIGS:
        print(f"Error: Unknown API '{api_name}'")
        print(f"Available APIs: {', '.join(API_CONFIGS.keys())}")
        return

    api_config = API_CONFIGS[api_name]

    if api_config["type"] == "graphql" and api_name == "admin":
        schema_path = os.path.join(
            shopify_dev_root, api_config["path_pattern"].format(version=version)
        )
        if not os.path.exists(schema_path):
            schema_path = os.path.join(
                shopify_dev_root, api_config["json_path_pattern"].format(version=version)
            )
            if os.path.exists(schema_path):
                api_config["type"] = "json"
            else:
                print(
                    f"Error: Schema file not found for {api_name} API version {version}"
                )
                print(f"Tried: {schema_path}")
                return
    else:
        schema_path = os.path.join(
            shopify_dev_root, api_config["path_pattern"].format(version=version)
        )
        if not os.path.exists(schema_path):
            print(
                f"Error: Schema file not found for {api_name} API version {version}"
            )
            print(f"Path: {schema_path}")
            return

    print(f"Processing {api_name} API schema from: {schema_path}")

    if api_config["type"] == "graphql":
        info = extract_queries_mutations_from_graphql(schema_path)
    else:
        info = extract_queries_mutations_from_json(schema_path)

    print(
        f"Found {len(info['queries'])} queries and {len(info['mutations'])} mutations"
    )

    if args.dry_run:
        print("\n--- Dry run mode: Extracted operations ---")
        print(f"\nQueries ({len(info['queries'])}):")
        for q in info["queries"][:5]:
            print(f"  - {q['name']}: {q['description'][:60]}...")
        if len(info["queries"]) > 5:
            print(f"  ... and {len(info['queries']) - 5} more")

        print(f"\nMutations ({len(info['mutations'])}):")
        for m in info["mutations"][:5]:
            print(f"  - {m['name']}: {m['description'][:60]}...")
        if len(info["mutations"]) > 5:
            print(f"  ... and {len(info['mutations']) - 5} more")
        print(
            "\n✓ Schema extraction successful! Use without --dry-run to generate test cases."
        )
        return

    try:
        actions_info = generate_actions(info, api_name)
        # Resolve promptfoo directory
        promptfoo_dir = os.path.normpath(
            os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..")
        )
        generate_yaml_file(actions_info, api_name, promptfoo_dir)
    except Exception as e:
        print(f"\n❌ Error generating test cases: {e}")
        print("\nPlease ensure:")
        print("  1. OPENAI_API_KEY environment variable is set")
        print("  2. OPENAI_ORGANIZATION environment variable is set (if needed)")
        print("  3. OPENAI_API_BASE_URL environment variable is set (if using a proxy)")
        print(
            "\nYou can use --dry-run to test schema extraction without generating test cases."
        )


if __name__ == "__main__":
    main()


